import contextvars
import threading
import weakref
from concurrent.futures import ThreadPoolExecutor


_REGISTERED_PROPAGATED_CONTEXTVARS_BY_ID = weakref.WeakValueDictionary()
_LOCK = threading.Lock()


def _register_contextvar(propagated_cv):
    with _LOCK:
        _enable_contextvar_propagation_to_new_threads()
        _enable_contextvar_propagation_to_executor_tasks()
        _REGISTERED_PROPAGATED_CONTEXTVARS_BY_ID[id(propagated_cv)] = propagated_cv


def _capture_registered_values():
    with _LOCK:
        registered = list(_REGISTERED_PROPAGATED_CONTEXTVARS_BY_ID.values())
    return [(propagated_cv._context_var, propagated_cv.get()) for propagated_cv in registered]


def _run_with_captured_values(captured_values, fn, *args, **kwargs):
    tokens = []
    try:
        for cv, value in captured_values:
            tokens.append((cv, cv.set(value)))
        return fn(*args, **kwargs)
    finally:
        for cv, token in reversed(tokens):
            cv.reset(token)


def _enable_contextvar_propagation_to_new_threads():
    if getattr(threading.Thread, "_dku_contextvar_thread_start_patched", False):
        return

    original_start = threading.Thread.start

    def _patched_start(self, *args, **kwargs):
        if not getattr(self, "_dku_contextvar_wrapped", False):
            original_run = self.run
            captured_values = _capture_registered_values()

            def _run_with_context(*run_args, **run_kwargs):
                return _run_with_captured_values(captured_values, original_run, *run_args, **run_kwargs)

            self.run = _run_with_context
            self._dku_contextvar_wrapped = True
        return original_start(self, *args, **kwargs)

    threading.Thread.start = _patched_start
    threading.Thread._dku_contextvar_thread_start_patched = True


def _enable_contextvar_propagation_to_executor_tasks():
    if getattr(ThreadPoolExecutor, "_dku_contextvar_submit_patched", False):
        return

    original_submit = ThreadPoolExecutor.submit

    def _patched_submit(self, fn, *args, **kwargs):
        captured_values = _capture_registered_values()

        def _run_with_context(*run_args, **run_kwargs):
            return _run_with_captured_values(captured_values, fn, *run_args, **run_kwargs)

        return original_submit(self, _run_with_context, *args, **kwargs)

    ThreadPoolExecutor.submit = _patched_submit
    ThreadPoolExecutor._dku_contextvar_submit_patched = True

class PropagatedContextVar:
    """
    ContextVar wrapper that lazily enables thread/executor propagation
    on first set(). This keeps patching opt-in for dataikuapi consumers.
    """

    def __init__(self, name, default=None):
        self._context_var = contextvars.ContextVar(name, default=default)

    def get(self, *args, **kwargs):
        return self._context_var.get(*args, **kwargs)

    def set(self, value):
        _register_contextvar(self)
        return self._context_var.set(value)

    def reset(self, token):
        self._context_var.reset(token)
